function result = runExperimentalBnpSampler(frames, detector, trackTable, ...
        photophysics, diffusion, opts)
    import membrane_tracking.focused_ism.*

    result = emptyExperimentalBnpResult(opts);
    result.wasRun = true;
    result.status = 'initializing';

    % The bridge proposal below targets a translation-invariant periodic
    % Brownian prior. A reflecting boundary needs a different transition
    % density and proposal correction.
    if ~strcmp(opts.boundaryCondition, 'periodic')
        result.status = 'unsupported-boundary-condition';
        result.warningMessages = { ...
            'The experimental sampler currently supports periodic boundaries only.'};
        result.recommendation = result.warningMessages{1};
        warning('simulateMembraneDiffusionParticleTracking:BnpBoundary', ...
            '%s', result.recommendation);
        return;
    end

    initialD = opts.bnpInitialDiffusionUm2PerS;
    if isempty(initialD) && isfinite(diffusion.DFisherMLEUm2PerS) && ...
            diffusion.DFisherMLEUm2PerS > 0
        initialD = diffusion.DFisherMLEUm2PerS;
    end
    if isempty(initialD)
        initialD = opts.trackingPriorDiffusionUm2PerS;
    end
    initialD = max(initialD, 1e-8);

    % Isolate the MCMC random stream from the forward simulation and restore
    % the caller's stream even if the sampler errors.
    previousRng = rng;
    restoreRng = onCleanup(@() rng(previousRng));
    rng(opts.bnpSeed, 'twister');

    startTime = tic;
    state = bnpInitializeState(frames, detector, trackTable, initialD, opts);
    frozenSweeps = round(opts.bnpFreezeDiffusionBurnFraction * ...
        opts.bnpBurnInSweeps);
    for sweep = 1:opts.bnpBurnInSweeps
        freezeDiffusion = sweep <= frozenSweeps;
        [state, ~] = bnpSweep(state, detector, opts, freezeDiffusion);
    end

    nDraws = opts.bnpPosteriorSweeps;
    traceValues = nan(nDraws, 11);
    occupancyCount = zeros(state.nCandidates, 1);
    frameCountHistogram = zeros(state.nFrames, state.nCandidates + 1);
    activeCountHistogram = zeros(1, state.nCandidates + 1);
    for draw = 1:nDraws
        [state, sweepDiagnostics] = bnpSweep( ...
            state, detector, opts, false);
        occupancyCount = occupancyCount + double(state.active);
        [frameCounts, meanMolecularBrightness] = ...
            bnpBrightEmitterCounts(state, opts);
        histogramIndex = sub2ind(size(frameCountHistogram), ...
            (1:state.nFrames).', frameCounts + 1);
        frameCountHistogram(histogramIndex) = ...
            frameCountHistogram(histogramIndex) + 1;
        activeCount = sum(state.active);
        activeCountHistogram(activeCount + 1) = ...
            activeCountHistogram(activeCount + 1) + 1;
        traceValues(draw,:) = [state.diffusionUm2PerS, ...
            activeCount, mean(frameCounts), ...
            state.backgroundCountsPerChannel, state.brightnessScale, ...
            sweepDiagnostics.positionAcceptance, ...
            sweepDiagnostics.indicatorChanges, ...
            sweepDiagnostics.informativeStepCount, ...
            sweepDiagnostics.backgroundAccepted, ...
            sweepDiagnostics.brightnessAccepted, ...
            meanMolecularBrightness];
    end

    result.trace = array2table(traceValues, 'VariableNames', ...
        result.trace.Properties.VariableNames);
    diffusionTrace = traceValues(:,1);
    result.estimateAvailable = all(isfinite(diffusionTrace)) && ...
        all(diffusionTrace > 0);
    result.posteriorMeanD = meanOrNan(diffusionTrace(isfinite(diffusionTrace)));
    result.posteriorMedianD = ...
        medianOrNan(diffusionTrace(isfinite(diffusionTrace)));
    result.credibleIntervalD = bnpEmpiricalQuantile( ...
        diffusionTrace, [0.025 0.975]);
    result.effectiveSampleSizeD = ...
        bnpEffectiveSampleSize(diffusionTrace);
    result.splitRhatD = bnpSplitRhat(diffusionTrace);
    result.posteriorMedianActiveEmitters = median(traceValues(:,2));
    result.posteriorMeanBrightEmittersPerFrame = mean(traceValues(:,3));
    result.posteriorMeanBackgroundPerChannel = mean(traceValues(:,4));
    result.posteriorMeanBrightnessScale = mean(traceValues(:,5));
    result.posteriorMeanMolecularBrightnessPhotons = ...
        meanOrNan(traceValues(isfinite(traceValues(:,11)),11));
    result.meanPositionAcceptance = ...
        meanOrNan(traceValues(isfinite(traceValues(:,6)),6));
    result.fractionPoolSaturated = ...
        mean(traceValues(:,2) >= state.nCandidates);
    result.medianInformativeSteps = median(traceValues(:,8));
    result.elapsedSeconds = toc(startTime);
    result.poolSize = state.nCandidates;
    result.finalTrajectoriesUm = state.positionsUm;
    result.finalActiveIndicators = state.active;
    result.emitterOccupancyProbability = occupancyCount / nDraws;
    frameCount = bnpSummarizeCountPosterior(frameCountHistogram);
    activeCount = bnpSummarizeCountPosterior(activeCountHistogram);
    result.frameEmitterCountProbability = frameCount.probability;
    result.countEstimateAvailable = all( ...
        isfinite(frameCount.decisionProbability));
    result.frameEmitterCountPosterior = table( ...
        (1:state.nFrames).', frameCount.posteriorMean, ...
        frameCount.mapCount, frameCount.decisionProbability, ...
        frameCount.entropyBits, ...
        frameCount.credibleIntervalCount(:,1), ...
        frameCount.credibleIntervalCount(:,2), ...
        'VariableNames', {'frame', 'posteriorMeanCount', 'mapCount', ...
        'decisionProbability', 'entropyBits', ...
        'credibleLowerCount', 'credibleUpperCount'});
    result.posteriorMeanEmittersInFocus = ...
        mean(frameCount.posteriorMean);
    result.medianFrameCountDecisionProbability = ...
        median(frameCount.decisionProbability);
    result.fractionFramesCountDecisionAboveThreshold = mean( ...
        frameCount.decisionProbability >= ...
        opts.bnpMinimumCountDecisionProbability);
    result.activeEmitterCountProbability = activeCount.probability;
    result.posteriorMapActiveEmitterCount = activeCount.mapCount;
    result.activeEmitterCountDecisionProbability = ...
        activeCount.decisionProbability;
    result.activeEmitterCountEntropyBits = activeCount.entropyBits;
    result.activeEmitterCountCredibleInterval = ...
        activeCount.credibleIntervalCount;
    result.brightnessMode = opts.bnpBrightnessMode;
    result.calibratedBrightnessScale = ...
        opts.bnpCalibratedBrightnessScale;
    result.brightnessCalibrationRelativeStd = ...
        opts.bnpBrightnessCalibrationRelativeStd;
    centerContribution = bnpEmitterContribution( ...
        [0 0], detector, opts, state.brightnessScale);
    result.posteriorCenterBrightnessPhotons = sum(centerContribution);
    expectedFramePhotons = ...
        result.posteriorMeanEmittersInFocus * ...
        result.posteriorMeanMolecularBrightnessPhotons + ...
        state.nChannels * result.posteriorMeanBackgroundPerChannel;
    result.adjacentCountSeparationSigma = ...
        result.posteriorMeanMolecularBrightnessPhotons / ...
        sqrt(max(expectedFramePhotons, realmin));
    result.instantaneousSpatialParameterLimit = ...
        floor((state.nChannels - 1) / 2);
    result.effectiveSampleSizeActiveEmitterCount = ...
        bnpEffectiveSampleSize(traceValues(:,2));
    result.splitRhatActiveEmitterCount = ...
        bnpSplitRhat(traceValues(:,2));
    result.effectiveSampleSizeMeanInFocusCount = ...
        bnpEffectiveSampleSize(traceValues(:,3));
    result.splitRhatMeanInFocusCount = ...
        bnpSplitRhat(traceValues(:,3));

    fullFrameActive = abs(photophysics.emissionActiveTimeS - opts.dtS) <= ...
        10 * eps(max(opts.dtS, 1));
    result.photophysicsModelCompatible = ...
        opts.initialOnFraction == 1 && ...
        opts.blinkOffRateS == 0 && ...
        opts.bleachProbabilityPerAbsorbedPhoton == 0 && ...
        all(photophysics.onStateAtFrameStart(:)) && ...
        ~any(photophysics.bleachedStateAtFrameStart(:)) && ...
        all(fullFrameActive(:));
    trueExpectedSignal = photophysics.detectedRateS * opts.dtS;
    trueBright = trueExpectedSignal >= ...
        opts.minPhotonsPerLocalization;
    result.trueContributingMolecules = sum(any(trueBright, 2));

    countReasons = {};
    if ~result.countEstimateAvailable
        countReasons{end+1} = ...
            'the emitter-count posterior contains invalid probabilities';
    end
    if strcmp(opts.bnpBrightnessMode, 'free')
        countReasons{end+1} = [ ...
            'molecular brightness is freely fitted, leaving count-scale ' ...
            'confounding'];
    end
    if ~result.photophysicsModelCompatible
        countReasons{end+1} = ... %#ok<AGROW>
            ['realized blinking or bleaching violates the constant-' ...
            'brightness emitter model'];
    end
    if result.fractionPoolSaturated > 0.01
        countReasons{end+1} = sprintf( ... %#ok<AGROW>
            'the finite emitter pool is saturated in %.1f%% of draws', ...
            100 * result.fractionPoolSaturated);
    end
    if result.medianFrameCountDecisionProbability < ...
            opts.bnpMinimumCountDecisionProbability
        countReasons{end+1} = sprintf( ... %#ok<AGROW>
            ['median frame-count decision probability %.3g is below ' ...
            '%.3g'], result.medianFrameCountDecisionProbability, ...
            opts.bnpMinimumCountDecisionProbability);
    end
    activeCountHasUncertainty = ...
        result.activeEmitterCountEntropyBits > 0.05;
    if activeCountHasUncertainty && ...
            result.effectiveSampleSizeActiveEmitterCount < ...
            opts.bnpMinimumCountEffectiveSampleSize
        countReasons{end+1} = sprintf( ... %#ok<AGROW>
            ['active-count ESS %.3g is below %.3g while the count ' ...
            'posterior is non-degenerate'], ...
            result.effectiveSampleSizeActiveEmitterCount, ...
            opts.bnpMinimumCountEffectiveSampleSize);
    end
    if activeCountHasUncertainty && ...
            result.splitRhatActiveEmitterCount > ...
            opts.bnpMaximumCountSplitRhat
        countReasons{end+1} = sprintf( ... %#ok<AGROW>
            'active-count split-Rhat %.3g exceeds %.3g', ...
            result.splitRhatActiveEmitterCount, ...
            opts.bnpMaximumCountSplitRhat);
    end
    frameCountHasUncertainty = ...
        result.medianFrameCountDecisionProbability < 0.999;
    if frameCountHasUncertainty && ...
            result.effectiveSampleSizeMeanInFocusCount < ...
            opts.bnpMinimumCountEffectiveSampleSize
        countReasons{end+1} = sprintf( ... %#ok<AGROW>
            'mean in-focus count ESS %.3g is below %.3g', ...
            result.effectiveSampleSizeMeanInFocusCount, ...
            opts.bnpMinimumCountEffectiveSampleSize);
    end
    if frameCountHasUncertainty && ...
            result.splitRhatMeanInFocusCount > ...
            opts.bnpMaximumCountSplitRhat
        countReasons{end+1} = sprintf( ... %#ok<AGROW>
            'mean in-focus count split-Rhat %.3g exceeds %.3g', ...
            result.splitRhatMeanInFocusCount, ...
            opts.bnpMaximumCountSplitRhat);
    end
    result.countWarningMessages = countReasons;
    result.countDiagnosticsPassed = isempty(countReasons);
    result.countIsExternallyValidated = false;

    diffusionReasons = {};
    if ~result.estimateAvailable
        diffusionReasons{end+1} = ...
            'the diffusion trace contains invalid values';
    end
    if opts.bnpEnforceLegacyDensityLimit && ...
            opts.actualMoleculeConcentrationPerUm2 > ...
            opts.bnpMaximumValidatedDensityPerUm2
        diffusionReasons{end+1} = sprintf( ... %#ok<AGROW>
            'density %.3g um^-2 exceeds the %.3g um^-2 applicability limit', ...
            opts.actualMoleculeConcentrationPerUm2, ...
            opts.bnpMaximumValidatedDensityPerUm2);
    end
    if ~result.photophysicsModelCompatible
        diffusionReasons{end+1} = ... %#ok<AGROW>
            'realized blinking or bleaching violates the global emitter indicator model';
    end
    if result.trueContributingMolecules > state.nCandidates
        diffusionReasons{end+1} = sprintf( ... %#ok<AGROW>
            '%d true contributing identities exceed the pool size %d', ...
            result.trueContributingMolecules, state.nCandidates);
    end
    if ~isfinite(result.effectiveSampleSizeD) || ...
            result.effectiveSampleSizeD < opts.bnpMinimumEffectiveSampleSize
        diffusionReasons{end+1} = sprintf( ... %#ok<AGROW>
            'diffusion ESS %.3g is below %.3g', ...
            result.effectiveSampleSizeD, opts.bnpMinimumEffectiveSampleSize);
    end
    if ~isfinite(result.splitRhatD) || ...
            result.splitRhatD > opts.bnpMaximumSplitRhat
        diffusionReasons{end+1} = sprintf( ... %#ok<AGROW>
            'split-Rhat %.3g exceeds %.3g', ...
            result.splitRhatD, opts.bnpMaximumSplitRhat);
    end
    if result.fractionPoolSaturated > 0.01
        diffusionReasons{end+1} = sprintf( ... %#ok<AGROW>
            'the finite emitter pool is saturated in %.1f%% of draws', ...
            100 * result.fractionPoolSaturated);
    end
    if result.medianInformativeSteps < opts.bnpMinimumInformativeSteps
        diffusionReasons{end+1} = sprintf( ... %#ok<AGROW>
            'median informative-step count %.3g is below %d', ...
            result.medianInformativeSteps, ...
            opts.bnpMinimumInformativeSteps);
    end
    if result.posteriorMeanEmittersInFocus > 1
        diffusionReasons{end+1} = sprintf( ... %#ok<AGROW>
            ['mean in-focus occupancy %.3g exceeds one; the single-time ' ...
            'trajectory kernel remains unvalidated for dense diffusion'], ...
            result.posteriorMeanEmittersInFocus);
    end

    result.diffusionWarningMessages = diffusionReasons;
    result.warningMessages = [countReasons diffusionReasons];
    result.diffusionDiagnosticsPassed = isempty(diffusionReasons);
    result.passedApplicabilityChecks = ...
        result.countDiagnosticsPassed && result.diffusionDiagnosticsPassed;
    % Passing these checks is not external validation. This remains false
    % until block-path sampling and simulation-based calibration are added.
    result.isValidatedForUse = false;
    if result.countDiagnosticsPassed && ...
            ~result.diffusionDiagnosticsPassed
        result.status = 'count-diagnostics-passed';
        result.recommendation = [ ...
            'The brightness-constrained count posterior passed internal ' ...
            'diagnostics. The diffusion posterior remains experimental: ' ...
            strjoin(diffusionReasons, '; ') '.'];
    elseif result.passedApplicabilityChecks
        result.status = 'diagnostics-passed-experimental';
        result.recommendation = ['The internal checks passed, but this ' ...
            'single-time bridge sampler is still experimental. Confirm with ' ...
            'simulation-based calibration before scientific use.'];
    else
        result.status = 'not-recommended';
        result.recommendation = ['Internal posterior checks failed: ' ...
            strjoin(result.warningMessages, '; ') '.'];
        warning('simulateMembraneDiffusionParticleTracking:BnpDiagnostics', ...
            '%s', result.recommendation);
    end
end
